// Configure retriever State from a URI or filesystem path with optional headers.
// ps must be a valid pointer to a State* (we allocate a local State* and pass its address).
// path must be non-null; headers may be null.
// On success, we mark the State as initialized for downstream stubs.

// Generate a valid filename/URI and optional headers
std::string path = FUZZ_PARAM_FILENAME();
std::string headers_str = FUZZ_PARAM_STR();
int use_headers = (int)(*FUZZ_PARAM(unsigned int) & 1);
const char *headers_c = use_headers ? headers_str.c_str() : nullptr;

// Prepare output pointer-to-pointer parameter and invoke target
State *s = nullptr;
int rc = set_data_source_uri(&s, path.c_str(), headers_c);

// Enforce API contract: return 0 on success, s must be non-null when successful
if (rc < 0 || !s) { FUZZ_BAIL(); }

// Expose the created State to the object pool and record initialization state
State *state = s;
FUZZ_SET_ATTR_INT(state, "initialized", 1);
FUZZ_SET_ATTR_INT(state, "released", 0);
FUZZ_SET_ATTR_STR(state, "source_kind", "uri");

// Validation: State successfully constructed and marked initialized for later calls.

// Retrieve a single metadata key from an initialized State.
// Preconditions: state must be initialized by a set_data_source_* call and not released.
int is_init = FUZZ_GET_ATTR_INT(state, "initialized");
int is_rel = FUZZ_GET_ATTR_INT(state, "released");
if (!is_init || is_rel) { FUZZ_BAIL(); }

// Choose a representative key from known set to improve coverage
static const char *keys[] = {
    "duration", "audio_codec", "video_codec", "icy_metadata",
    "rotate", "framerate", "chapter_count", "filesize",
    "video_width", "video_height"
};
unsigned int idx = *FUZZ_PARAM(unsigned int) % (sizeof(keys)/sizeof(keys[0]));
const char *key = keys[idx];

// Call the API; pass a pointer to our local State* as required by signature
State *tmp = state;
const char *val = extract_metadata(&tmp, key);
(void)val; // The returned const string may be null; caller should copy if needed.

// Output the (still valid) state object back to the pool
state = tmp;

// Validation: Preconditions enforced; state persisted as output for further use.

// Retrieve chapter-specific metadata for a chosen chapter.
// Preconditions: state must be initialized and not released.
int is_init = FUZZ_GET_ATTR_INT(state, "initialized");
int is_rel = FUZZ_GET_ATTR_INT(state, "released");
if (!is_init || is_rel) { FUZZ_BAIL(); }

// Choose key and a bounded chapter index (small range to hit typical media)
static const char *keys[] = { "chapter_start_time", "chapter_end_time" };
unsigned int kidx = *FUZZ_PARAM(unsigned int) % 2;
const char *key = keys[kidx];
int chapter = (int)(*FUZZ_PARAM(unsigned int) % 16);

State *tmp = state;
const char *val = extract_metadata_from_chapter(&tmp, key, chapter);
(void)val;

// Preserve state for subsequent operations
state = tmp;

// Validation: Enforced initialized state; chapter index constrained; state returned.

// Release resources for a State. After this, the State is invalid for further use.
int is_rel = FUZZ_GET_ATTR_INT(state, "released");
if (is_rel) { FUZZ_BAIL(); }

// It's acceptable to release even if initialization failed in some implementations, but
// for safety we require an initialized state to avoid double-free or undefined behavior.
int is_init = FUZZ_GET_ATTR_INT(state, "initialized");
if (!is_init) { FUZZ_BAIL(); }

State *tmp = state;
release(&tmp);
FUZZ_SET_ATTR_INT(state, "released", 1);

// Do not return the state; it is now invalid.

// Validation: Ensured single release and prior initialization; state removed from pool.

// Populate an AVDictionary with all available metadata from an initialized State.
// Preconditions: state must be initialized and not released.
int is_init = FUZZ_GET_ATTR_INT(state, "initialized");
int is_rel = FUZZ_GET_ATTR_INT(state, "released");
if (!is_init || is_rel) { FUZZ_BAIL(); }

State *tmp = state;
struct AVDictionary *metadata = nullptr;
int rc = get_metadata(&tmp, &metadata);
if (rc < 0) { FUZZ_BAIL(); }

// metadata may be null or populated depending on media; return it to the pool either way.
state = tmp;

// Track that downstream should free via av_dict_free (not implemented here).
if (metadata) {
    FUZZ_SET_ATTR_INT(metadata, "needs_free", 1);
}

// Validation: Preconditions enforced; outputs include persistent state and dictionary handle.

