import os
import random
import struct
from typing import List

# This generator produces a valid media path/URI string buffer, possibly accompanied
# by optional HTTP headers in the same buffer separated by a NUL. The stub calls
# FUZZ_PARAM_FILENAME() for the path/URI and FUZZ_PARAM_STR() for headers. Many fuzz
# harnesses will slice the provided bytes into independent consumptions; to maximize
# usefulness across harnesses, we place two consecutive C-strings:
# [path_or_uri]\0[optional_headers]\0
# If the harness ignores the second string (when use_headers==0), it remains harmless.
# If it uses headers, it will find a well-formed header block.
#
# The path/URI is chosen from a curated set that FFmpeg commonly supports, including
# local files and common network protocols. We include a variety of extensions and
# query/fragment variations to exercise different demuxers and options.
#
# The headers string, when present, is a sequence of HTTP-style headers separated by
# CRLF and ending with CRLF. We randomize common headers relevant to FFmpeg.

LOCAL_BASENAMES = [
    "sample.mp4", "sample.mkv", "sample.webm", "sample.mov", "sample.avi",
    "sample.flv", "sample.mpeg", "sample.ts", "sample.m4a", "sample.mp3",
    "sample.aac", "sample.flac", "sample.ogg", "sample.wav", "cover.jpg",
]

LOCAL_DIRS = [
    ".", "/tmp", "/var/tmp", "/sdcard/Movies", "/sdcard/Music", "/data/local/tmp",
]

HTTP_HOSTS = [
    "example.com", "localhost", "127.0.0.1", "::1", "media.example", "cdn.example",
]

HTTP_PATHS = [
    "/video.mp4", "/stream.m3u8", "/index.m3u8", "/dash.mpd", "/audio.mp3",
    "/track.flac", "/movie.mkv", "/clip.webm", "/cover.jpg",
]

QUERY_OPTIONS = [
    "", "?token=abcd", "?start=10", "?end=20", "?range=0-", "?download=1",
    "?quality=hd", "?auth=true#frag", "#t=10",
]

RTSP_PATHS = [
    "/live", "/camera", "/stream1", "/h264", "/mpeg4",
]

FTP_PATHS = [
    "/pub/sample.avi", "/pub/video.mpeg", "/pub/audio.mp3",
]

SCHEMES = [
    "file", "http", "https", "rtsp", "ftp",
]

# Reasonable header fields FFmpeg may parse
HEADER_FIELDS = [
    "User-Agent", "Range", "Icy-MetaData", "Accept", "Referer", "Connection",
    "Accept-Language", "Authorization", "Cookie", "Host",
]

USER_AGENTS = [
    "Lavf/59.27.100", "FFmpeg/5.1", "Mozilla/5.0", "curl/7.79.1",
]

ACCEPTS = [
    "*/*", "video/*", "audio/*", "application/vnd.apple.mpegurl",
]

REFERRERS = [
    "https://example.com/", "https://player.example/video",
]

RANGES = [
    "bytes=0-", "bytes=1024-", "bytes=0-4095",
]

AUTH_BASICS = [
    "Basic Zm9vOmJhcg==", "Bearer abcdef123456", "",
]

COOKIES = [
    "session=deadbeef; path=/; HttpOnly", "prefs=quality=hd", "",
]


def _choose(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]


def _build_local_path(rng: random.Random) -> str:
    base = _choose(rng, LOCAL_BASENAMES)
    if rng.random() < 0.6:
        d = _choose(rng, LOCAL_DIRS)
        return f"{d}/{base}"
    # Relative nested path
    depth = rng.randint(0, 3)
    parts = [".." if rng.random() < 0.3 else "folder" + str(i) for i in range(depth)]
    parts.append(base)
    return "/".join(parts) if parts else base


def _build_http_uri(rng: random.Random, secure: bool) -> str:
    scheme = "https" if secure else "http"
    host = _choose(rng, HTTP_HOSTS)
    path = _choose(rng, HTTP_PATHS)
    q = _choose(rng, QUERY_OPTIONS)
    # Optional embedded credentials
    if rng.random() < 0.2:
        user = "user" if rng.random() < 0.5 else "u"
        pwd = "pass" if rng.random() < 0.5 else "p"
        auth = f"{user}:{pwd}@"
    else:
        auth = ""
    # Optional port
    port = ":80" if (not secure and rng.random() < 0.3) else (":443" if (secure and rng.random() < 0.2) else "")
    # IPv6 literal needs brackets
    if ":" in host and not host.startswith("["):
        host_fmt = f"[{host}]"
    else:
        host_fmt = host
    return f"{scheme}://{auth}{host_fmt}{port}{path}{q}"


def _build_rtsp_uri(rng: random.Random) -> str:
    host = _choose(rng, HTTP_HOSTS)
    path = _choose(rng, RTSP_PATHS)
    transport = ";tcp" if rng.random() < 0.5 else ";udp"
    return f"rtsp://{host}{path}{transport}"


def _build_ftp_uri(rng: random.Random) -> str:
    host = _choose(rng, HTTP_HOSTS)
    path = _choose(rng, FTP_PATHS)
    creds = "anonymous:guest@" if rng.random() < 0.5 else ""
    return f"ftp://{creds}{host}{path}"


def _build_file_uri(rng: random.Random) -> str:
    path = _build_local_path(rng)
    # Encode as file:// URI if absolute, otherwise leave as path
    if path.startswith("/"):
        return f"file://{path}"
    return path


def _build_headers(rng: random.Random) -> str:
    lines = []
    # Always include Host for HTTP(S) URIs
    host = _choose(rng, HTTP_HOSTS)
    lines.append(f"Host: {host}")
    if rng.random() < 0.9:
        lines.append(f"User-Agent: {_choose(rng, USER_AGENTS)}")
    if rng.random() < 0.6:
        lines.append(f"Accept: {_choose(rng, ACCEPTS)}")
    if rng.random() < 0.5:
        lines.append(f"Referer: {_choose(rng, REFERRERS)}")
    if rng.random() < 0.5:
        lines.append(f"Range: {_choose(rng, RANGES)}")
    if rng.random() < 0.5:
        lines.append("Icy-MetaData: 1")
    if rng.random() < 0.4:
        auth = _choose(rng, AUTH_BASICS)
        if auth:
            lines.append(f"Authorization: {auth}")
    if rng.random() < 0.4:
        cookie = _choose(rng, COOKIES)
        if cookie:
            lines.append(f"Cookie: {cookie}")
    # Add a few random extra headers
    extra = [h for h in HEADER_FIELDS if not any(h.startswith(k) for k in ["User-Agent", "Accept", "Range", "Icy-MetaData", "Authorization", "Cookie", "Host", "Referer"]) ]
    rng.shuffle(extra)
    for h in extra[:rng.randint(0, 2)]:
        lines.append(f"{h}: value")
    return "\r\n".join(lines) + "\r\n"


def _build_path_or_uri(rng: random.Random) -> str:
    scheme = _choose(rng, SCHEMES)
    if scheme == "file":
        return _build_file_uri(rng)
    if scheme == "http":
        return _build_http_uri(rng, secure=False)
    if scheme == "https":
        return _build_http_uri(rng, secure=True)
    if scheme == "rtsp":
        return _build_rtsp_uri(rng)
    if scheme == "ftp":
        return _build_ftp_uri(rng)
    return _build_file_uri(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    uri = _build_path_or_uri(rng)
    headers = _build_headers(rng) if rng.random() < 0.8 else ""

    # Compose as two C-strings: path/URI NUL headers NUL
    # Ensure overall size <= 4096 bytes
    def enc(s: str) -> bytes:
        return s.encode('utf-8', errors='replace')

    uri_b = enc(uri)
    headers_b = enc(headers)

    # Truncate if necessary to respect 4096 limit (keeping both strings intact where possible)
    max_total = 4096
    # We need two NULs
    overhead = 2
    if len(uri_b) + len(headers_b) + overhead > max_total:
        # Prefer keeping URI intact; trim headers first
        max_headers = max_total - len(uri_b) - overhead
        if max_headers < 0:
            # URI alone is too large; trim URI
            uri_b = uri_b[: max_total - overhead]
            headers_b = b""
        else:
            headers_b = headers_b[:max_headers]
    out = uri_b + b"\x00" + headers_b + b"\x00"
    return out
